const legacy=location.hash.match(/^#\/(vehicle\/[\w-]+|guide|privacy|account|admin|)$/);
if(legacy){const target=legacy[1].replace(/^vehicle\//,'ilan/');location.replace('/'+target);}
const routeHash=()=>location.pathname.startsWith('/ilan/')?'#/vehicle/'+location.pathname.slice(6):'#'+location.pathname;
'use strict';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),intro=$('#site-intro');
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const introFirstVisit=document.documentElement.classList.contains('show-intro');
let introStarted=performance.now();
function finishIntro(){if(!intro)return;const wait=introFirstVisit&&!reduceMotion?Math.max(0,3000-(performance.now()-introStarted)):0;setTimeout(()=>{intro.classList.add('intro-out');setTimeout(()=>intro.remove(),reduceMotion?0:420);},wait);}
async function smoothRoute(){if(reduceMotion||!document.startViewTransition)return route();const transition=document.startViewTransition(()=>route());await transition.finished;}
async function navigate(path,{replace=false}={}){const current=location.pathname+location.search+location.hash;if(path===current)return;history[replace?'replaceState':'pushState'](null,'',path);await smoothRoute();}
const state={user:null,vehicles:[],categories:[],roles:[],query:'',category:'Tümü',sort:'new',onlyFollow:false,total:0,hasMore:false,demo:false};
