async function api(path,body){let r;try{r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw new Error('Bağlantı kurulamadı. Lütfen sarisiteyorumla.com adresinden tekrar deneyin.');}let d;try{d=await r.json();}catch{throw new Error('Sunucudan geçerli yanıt alınamadı. Lütfen sayfayı yenileyin.');}if(!r.ok)throw new Error(d.error||'İşlem tamamlanamadı.');return d;}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function logo(){return '<a class="brand" href="/" aria-label="Sarı Site Yorumla ana sayfa"><img class="brand-symbol" src="/brand-symbol.svg" alt="" width="44" height="44"><span class="brand-words"><strong>sarı site</strong><span>yorumla<span class="logo-dot">.</span></span></span><sup>BETA</sup></a>';}
function activeRoute(){const p=location.pathname.replace(/\/+$/,'')||'/';const h=(location.hash||'').replace(/^#/,'').replace(/^\/vehicle\//,'/ilan/').replace(/\/+$/,'')||'';if(h&&h!=='/')return h;return p;}
function header(){const cur=activeRoute(),onHome=cur==='/',onGuide=cur==='/guide',onFollow=cur==='/takip',onAccount=cur==='/account',followLink=state.user?`<a href="/takip" class="${onFollow?'active':''}"${onFollow?' aria-current="page"':''} data-action="follow-nav">Takip ettiklerim</a>`:'',mobileFollow=state.user?`<a href="/takip" class="${onFollow?'active':''}"${onFollow?' aria-current="page"':''} data-action="follow-nav">${icon('heart')}<span>Takip ettiklerim</span></a>`:'';return `<header><div class="wrap nav">${logo()}<nav class="desktop-nav" aria-label="Ana gezinme"><a href="/" class="${onHome?'active':''}"${onHome?' aria-current="page"':''}>İlanları keşfet</a><a href="/guide" class="${onGuide?'active':''}"${onGuide?' aria-current="page"':''}>Nasıl çalışır?</a>${followLink}</nav><div class="nav-actions">${state.user?`<button class="text-button header-account ${onAccount?'active':''}"${onAccount?' aria-current="page"':''} data-action="account">${icon('circle-user-round')}<span class="account-name">${esc(state.user.name)}</span>${icon('chevron-right')}</button>`:`<button class="text-button header-account ${onAccount?'active':''}"${onAccount?' aria-current="page"':''} data-action="login">${icon('circle-user-round')}<span class="account-name">Giriş yap</span></button>`}<button class="button small dark header-add" data-action="add">${icon('plus')}<span>İlan aç</span></button><button class="mobile-menu-toggle" type="button" data-action="menu-toggle" aria-label="Menüyü aç" aria-controls="mobile-menu" aria-expanded="false">${icon('menu')}</button></div></div><nav id="mobile-menu" class="mobile-menu" aria-label="Mobil gezinme"><a href="/" class="${onHome?'active':''}"${onHome?' aria-current="page"':''}>${icon('house')}<span>İlanları keşfet</span></a><a href="/guide" class="${onGuide?'active':''}"${onGuide?' aria-current="page"':''}>${icon('message-circle')}<span>Nasıl çalışır?</span></a>${mobileFollow}<button class="mobile-menu-add" data-action="add">${icon('plus')}<span>İlan aç</span></button>${state.user?`<button class="mobile-menu-user ${onAccount?'active':''}"${onAccount?' aria-current="page"':''} data-action="account" aria-label="${esc(state.user.name)} hesabını aç"><span class="mobile-menu-avatar" aria-hidden="true">${esc(state.user.name.trim().slice(0,1).toLocaleUpperCase('tr'))}</span><span class="mobile-menu-user-copy"><strong>${esc(state.user.name)}</strong><small>Hesabım</small></span>${icon('chevron-right')}</button>`:`<button class="${onAccount?'active':''}"${onAccount?' aria-current="page"':''} data-action="login">${icon('circle-user-round')}<span>Giriş yap</span></button>`}</nav></header>`;}
function footer(){const cur=activeRoute(),links=[['/about','Proje hakkında'],['/terms','Kullanım koşulları'],['/guide','Topluluk kuralları'],['/privacy','KVKK aydınlatma metni'],['/cookies','Çerezler']];return `<footer class="wrap"><div>${logo()}<p>İlana bak. Bilene sor. Yorumla.</p></div><div>${links.map(([path,label])=>`<a href="${path}" class="${cur===path?'active':''}"${cur===path?' aria-current="page"':''}>${label}</a>`).join('')}<a href="https://github.com/shreddedcoderx/sari-site-yorumla" target="_blank" rel="noopener noreferrer">GitHub · Açık kaynak</a><span>© ${new Date().getFullYear()} Sarı Site Yorumla</span></div><p class="fineprint">Bağımsız, kâr amacı gütmeyen kişisel bir topluluk projesidir. Diğer ilan platformlarıyla resmî bağlantısı yoktur. Yorumlar kullanıcı deneyimidir; ekspertiz yerine geçmez.</p></footer>`;}
function options(arr,selected){return arr.map(v=>`<option${v===selected?' selected':''}>${esc(v)}</option>`).join('');}
function representativeCar(v){
 const number=String(v.listing_no),shapes=[
  {roof:'L205 112 Q224 91 253 91 H373 Q401 91 422 112 L464 146',glass:'M217 141 240 111 Q246 104 259 104 H369 Q385 104 397 116 L422 141 Z'},
  {roof:'L194 105 Q209 89 235 89 H389 Q415 89 433 108 L466 146',glass:'M207 141 226 110 Q232 103 242 103 H384 Q401 103 409 114 L433 141 Z'},
  {roof:'L209 111 Q230 91 258 91 H379 Q416 94 443 124 L466 146',glass:'M220 141 244 113 Q252 104 265 104 H376 Q402 105 423 125 L439 141 Z'},
  {roof:'L223 118 Q251 94 283 92 H382 Q411 94 439 120 L467 146',glass:'M236 141 262 117 Q273 105 287 105 H378 Q401 105 419 122 L439 141 Z'}
 ];
 const colors=[['#526d82','#eaf0ef'],['#9d5947','#f4eee8'],['#73866d','#edf0e5'],['#bd9b4e','#f5f0dd'],['#6d6884','#f0edf3'],['#666e6a','#ecefed']];
 let seed=2166136261;for(const char of number)seed=Math.imul(seed^char.charCodeAt(0),16777619)>>>0;
 const shape=shapes[seed%shapes.length],[paint,sky]=colors[(seed>>>3)%colors.length],stripe=(seed>>>8)%2;
 return `<figure class="representative-car" role="img" aria-label="İlan #${esc(number)} için temsili araç çizimi"><svg viewBox="0 0 640 300" aria-hidden="true" focusable="false"><rect width="640" height="300" fill="${sky}"/><circle cx="${85+(seed%75)}" cy="66" r="38" fill="#fff" opacity=".52"/><path d="M0 236 Q160 219 320 235 T640 232 V300 H0Z" fill="#e1e4dc"/><ellipse cx="322" cy="226" rx="241" ry="18" fill="#59635d" opacity=".15"/><path d="M105 174 Q111 155 139 152 L171 146 ${shape.roof} H501 Q531 147 538 174 L545 190 Q547 202 532 202 H111 Q98 202 99 190Z" fill="${paint}" stroke="#303834" stroke-width="4" stroke-linejoin="round"/><path d="${shape.glass}" fill="#b6c9ca" stroke="#303834" stroke-width="3" stroke-linejoin="round"/><path d="M326 105 V141 M331 146 V189 M153 158 H475" fill="none" stroke="#303834" stroke-width="3" opacity=".7"/><path d="M351 155 h22" stroke="#303834" stroke-width="4" stroke-linecap="round"/>${stripe?'<path d="M389 176 h56" stroke="#fff" stroke-width="5" opacity=".42"/>':''}<path d="M116 166 h18 l-4 13 h-21Z" fill="#bb5d4a"/><path d="M515 165 h17 l6 16 h-22Z" fill="#fff3bc"/><circle cx="202" cy="200" r="31" fill="#222a28"/><circle cx="455" cy="200" r="31" fill="#222a28"/><circle cx="202" cy="200" r="17" fill="#dce1d9"/><circle cx="455" cy="200" r="17" fill="#dce1d9"/><circle cx="202" cy="200" r="5" fill="#798680"/><circle cx="455" cy="200" r="5" fill="#798680"/><rect x="283" y="181" width="73" height="17" rx="3" fill="#f4f2e8" stroke="#303834" stroke-width="2"/><text x="319.5" y="193" fill="#303834" font-family="Arial,sans-serif" font-size="10" text-anchor="middle">${esc(number.slice(-4))}</text></svg><figcaption>Otomatik oluşturulmuş temsili çizim</figcaption></figure>`;
}
function listingArt(v){return `<div class="listing-art"><span class="listing-art-label">İLAN NUMARASI</span><span class="listing-art-number">#${esc(v.listing_no||v.id)}</span><span class="listing-art-chat"><i></i><i></i><i></i></span></div>`;}
function card(v){const number=esc(v.listing_no||v.id);return `<article class="vehicle-card${v.status==='suspended'?' suspended-card':''}"><a class="vehicle-image" href="/ilan/${v.id}">${listingArt(v)}${v.status==='suspended'?'<span class="suspended-label">ASKIDA</span>':''}</a><button class="save ${v.following?'saved':''}" aria-label="${v.following?'Takibi bırak':'İlanı takip et'}" data-action="follow" data-id="${v.id}"${v.status==='suspended'?' disabled title="İlan askıda"':''}>${icon('heart')}</button><div class="vehicle-body"><a href="/ilan/${v.id}" class="vehicle-title">İlan #${number}</a><p class="specs">${v.comment_count} yorum</p><a class="card-bottom" href="/ilan/${v.id}"><span>Yorumları oku</span><span>${icon('chevron-right')}</span></a></div></article>`;}
function vehiclePath(offset=0){const p=new URLSearchParams({limit:'24',offset:String(offset),sort:state.sort});if(state.category!=='Tümü')p.set('category',state.category);if(state.query)p.set('query',state.query);if(state.onlyFollow)p.set('following','1');return '/vehicles?'+p;}
async function loadVehicles(reset=true){const d=await api(vehiclePath(reset?0:state.vehicles.length));state.vehicles=reset?d.vehicles:[...state.vehicles,...d.vehicles];state.total=d.total;state.hasMore=d.hasMore;renderGrid();}
function filtered(){return state.vehicles;}
function home(){app.innerHTML=header()+`<main><section class="hero wrap"><div class="hero-copy"><div class="overline"><span class="live-dot"></span> İLANIN NUMARASI VAR. BİR DE YORUMLARI.</div><h1>İlanı gördün.<br>Bir de <em>yorumlara</em> bak.</h1><p>Sarı sitedeki araç ilanını buraya getir. Eski sahiplerin ve aracı<br class="desktop"> görmüş insanların deneyimlerini oku, sen de bildiğini paylaş.</p><form id="search" class="searchbox"><span aria-hidden="true">⌕</span><input aria-label="İlan numarası veya bağlantısı ara" name="query" placeholder="İlan numarasını veya sarı site bağlantısını yapıştır…" value="${esc(state.query)}"><button class="button orange" type="submit">Yorumlara bak <span>${icon('arrow-up-right','inline-icon')}</span></button></form><p id="search-feedback" class="search-feedback" role="status" aria-live="polite" hidden></p><div class="hero-tags"><span>${icon('check','inline-icon')} Eski sahip deneyimleri</span><span>${icon('check','inline-icon')} Açık sözlü yorumlar</span><span>${icon('check','inline-icon')} Topluluk incelemesi</span></div></div><aside class="hero-story"><div class="story-top"><span class="story-tag">İLAN → SOHBET</span><span class="story-star">${icon('arrow-up-right','inline-icon')}</span></div><div class="sample-listing"><span>İLAN NUMARASI</span><strong class="sample-number" aria-label="Örnek ilan numarası"><span class="sample-hash">#</span><span>XXXXXXXXXX</span></strong><div class="listing-rule"></div><p>İlanda yazanlar bir yere kadar.</p><h2>Asıl mesele,<br><span>bilenlerin anlattıkları.</span></h2></div><div class="story-bottom"><span class="bubble-mark">“</span><p>Eski sahibi misin? Aracı gördün mü?<br><strong>Söz sende. Deneyimini paylaş.</strong></p></div><span class="example-note">Örnek ilan numarası · İlan içeriği otomatik alınmaz</span></aside></section><div class="trust-band"><div class="wrap"><span>İLANI BUL · YORUMLARI OKU · DENEYİMİNİ PAYLAŞ</span><strong>Aynı ilan. Farklı deneyimler.</strong><span>Bağımsız <b>·</b> Şeffaf <b>·</b> Topluluktan</span></div></div><section class="explore wrap" id="explore"><div class="section-title"><div><span class="eyebrow">TOPLULUĞUN KONUŞTUĞU İLANLAR</span><h2>${state.onlyFollow?'Takip ettiğin ilanlar':'İlanın altında buluşalım.'}</h2></div><p>Bir yorum, birinin kararını değiştirebilir.</p></div><div class="filters"><div class="tabs" role="group" aria-label="Araç kategorisi">${['Tümü',...state.categories].map(c=>`<button class="tab ${state.category===c?'selected':''}" data-action="category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><label class="sort-label">Sırala <select id="sort" aria-label="Araçları sırala"><option value="new">En yeni eklenen</option><option value="comments"${state.sort==='comments'?' selected':''}>En çok yorumlanan</option><option value="price"${state.sort==='price'?' selected':''}>Fiyat: düşükten yükseğe</option></select></label></div><div class="results-line"><span id="result-count"></span>${state.onlyFollow?'<button class="text-button" data-action="all">Tüm ilanları göster ×</button>':''}${state.demo?'<span class="demo-label">Önizleme · Araçlar ve yorumlar örnektir</span>':''}</div><div class="vehicle-grid" id="grid"></div><div class="community-banner"><span class="banner-icon">${icon('arrow-up-right','inline-icon')}</span><div><h3>O ilan hakkında söyleyeceklerin mi var?</h3><p>Eski aracın satışta mı? İlandaki aracı görmeye gittin mi?<br>İlan numarasını gir, kendi deneyimini paylaş.</p></div><button class="button dark" data-action="add">Yeni ilan aç <span>${icon('plus','inline-icon')}</span></button></div></section><section class="how wrap"><div><span class="eyebrow">ÜÇ ADIMDA SARI SİTE YORUMLA</span><h2>İlandan yoruma.<br>Üç kısa adım.</h2><a href="/guide" class="inline-link">Topluluğu tanı ${icon('arrow-up-right','inline-icon')}</a></div><article><span>01</span><h3>İlan numarasını gir.</h3><p>İlan numarasını veya bağlantısını gir. Aynı ilana ait deneyimleri tek sayfada bul.</p></article><article><span>02</span><h3>Hikâyesini dinle.</h3><p>Eski sahiplerin, aracı görenlerin ve ekspertize götürenlerin deneyimlerini oku.</p></article><article><span>03</span><h3>Sen de yorumla.</h3><p>Bildiğini anlat. Gözlemini ve yorumunu ayır, diğer alıcılara yol göster.</p></article></section></main>`+footer();renderGrid();}
function renderGrid(){const rows=filtered();$('#result-count').textContent=`${state.total} ilan ${state.query?'· “'+state.query+'”':''}`;$('#grid').innerHTML=rows.length?rows.map(card).join('')+(state.hasMore?'<div class="load-more"><button class="button outline" data-action="more">Daha fazla ilan göster</button></div>':''):`<div class="empty"><span>${icon('car-front')}</span><h3>${state.onlyFollow?'Takip listen henüz boş.':'Bu ilanın ilk sözünü sen söyle.'}</h3><p>${state.query?'Aramana uygun ilan bulunamadı. İlan numarasıyla da arayabilirsin.':'Henüz araç eklenmemiş. İlk ilanı ekle, deneyimleri bir araya getirelim.'}</p><button class="button dark" data-action="add">${icon('plus')} Yeni ilan aç</button></div>`;}
function openModal(title,html){modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Pencereyi kapat">${icon('x')}</button></div>${html}`;modal.showModal();document.documentElement.classList.add("modal-open");}
function auth(register=false){openModal(register?'Topluluğa katıl.':'Tekrar merhaba.',`<p class="muted">${register?'Bir deneyimin, birinin yolunu değiştirebilir.':'Yarım kalan hikâyelere devam et.'}</p><form id="auth-form" class="form" data-register="${register}">${register?'<label>Görünen ad<input name="name" required minlength="2" maxlength="40" autocomplete="nickname" placeholder="Yorumlarında görünecek ad"></label>':''}<label>E-posta<input type="email" name="email" required autocomplete="email" maxlength="254" placeholder="sen@ornek.com"></label><label>Şifre<input type="password" name="password" required minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="En az 12 karakter"></label>${register?'<label class="checkbox"><input name="acceptTerms" type="checkbox" required> <span><a href="/terms" target="_blank" rel="noopener noreferrer">Kullanım koşullarını</a> okudum, kabul ediyorum.</span></label><label class="checkbox"><input name="acceptRules" type="checkbox" required> <span><a href="/guide" target="_blank" rel="noopener noreferrer">Topluluk kurallarını</a> okudum, kabul ediyorum.</span></label><p class="fineprint">Kişisel verilerinin nasıl işlendiğini <a href="/privacy" target="_blank" rel="noopener noreferrer">KVKK aydınlatma metninden</a> ve <a href="/cookies" target="_blank" rel="noopener noreferrer">çerez bilgisinden</a> öğrenebilirsin. Aydınlatma metni için ayrıca onay istenmez.</p><p class="fineprint">E-posta adresin halka gösterilmez. Bu ilk sürümde e-posta doğrulaması ve şifre yenileme bulunmuyor.</p>':''}<p class="form-error" role="alert"></p><button class="button orange full" type="submit">${register?'Hesabımı oluştur':'Giriş yap'} ${icon('arrow-up-right','inline-icon')}</button></form><p class="modal-switch">${register?'Zaten üye misin?':'Henüz üye değil misin?'} <button class="text-button" data-action="${register?'login':'register'}">${register?'Giriş yap':'Ücretsiz katıl'}</button></p>`);}
function needUser(){if(state.user)return true;auth();return false;}
function addVehicle(){if(!needUser())return;openModal('Yeni ilan aç.',`<p class="muted">Yalnızca ilan numarası ve kategori seç. İlan onaylandıktan sonra kullanıcılar yorum ve fiyat kaydı ekleyebilir.</p><form id="listing-form" class="form"><label>İlan numarası<input name="listing" required inputmode="numeric" pattern="[0-9]{8,12}" minlength="8" maxlength="12" placeholder="Örn. 1318443200" autocomplete="off"></label><label>Kategori<select name="category" required><option value="">Kategori seç</option>${options(state.categories)}</select></label><p class="fineprint">Aynı ilan numarasıyla ikinci sayfa açılamaz. İlan içeriği otomatik alınmaz.</p><p class="form-error" role="alert"></p><button class="button orange full" type="submit">İlanı incelemeye gönder ${icon('arrow-up-right','inline-icon')}</button></form>`);}
async function detail(id){const d=await api('/vehicles/'+id),v=d.vehicle;app.innerHTML=header()+`<main class="wrap detail${v.status==='suspended'?' suspended':''}"><a class="back" href="/">${icon('arrow-left','inline-icon')} İlanları keşfet</a>${v.status==='suspended'?'<div class="suspension-notice" role="status"><strong>Bu ilan geçici olarak askıya alındı.</strong><span>Sayfa görüntülenebilir; askı süresince tüm etkileşimler kapalıdır.</span></div>':''}${state.user&&(state.user.admin||state.user.id===v.user_id&&v.status!=='suspended')?`<div class="listing-management"><div><span class="eyebrow">${state.user.admin?'YÖNETİCİ İŞLEMLERİ':'İLAN YÖNETİMİ'}</span><strong>${state.user.admin?'İlanı yönet':'Eklediğin ilanı yönet'}</strong></div><div class="listing-management-actions">${v.status==='removed'&&!state.user.admin&&!v.owner_removed?'':`<button class="button outline" data-action="edit-listing" data-id="${v.id}">Düzenle</button>`}${state.user.admin?vehicleActions(v):v.status==='removed'?v.owner_removed?`<button class="button dark" data-action="restore-listing" data-id="${v.id}">Yeniden incelemeye gönder</button>`:'':`<button class="button outline" data-action="remove-listing" data-id="${v.id}">İlanı kaldır</button>`}</div></div>`:''}<div class="detail-layout"><section>${v.listing_no?representativeCar(v):''}${v.listing_no?`<div class="listing-number-panel"><span class="eyebrow">İLAN NUMARASI</span><div class="listing-number-display" aria-label="İlan numarası ${esc(v.listing_no)}"><strong><span class="listing-number-hash">#</span>${esc(v.listing_no)}</strong></div><div class="listing-number-actions"><button type="button" class="listing-number-copy" data-action="copy-listing" data-number="${esc(v.listing_no)}" aria-label="İlan numarasını kopyala">${icon('copy')}<span>Kopyala</span></button></div></div>`:`<div class="listing-number-panel"><span class="eyebrow">ÖRNEK İLAN KİMLİĞİ</span><div class="listing-number-display" aria-label="Örnek ilan kimliği ${esc(v.id)}"><strong><span class="listing-number-hash">#</span>${esc(v.id)}</strong></div><div class="listing-number-actions"><button type="button" class="listing-number-copy" data-action="copy-listing" data-number="${esc(v.id)}" aria-label="Örnek ilan kimliğini kopyala">${icon('copy')}<span>Kimliği kopyala</span></button></div></div>`}${v.status==='suspended'?'':v.status==='removed'?'<p class="notice">Bu ilan yayından kaldırıldı.</p>':v.status!=='approved'?'<p class="notice">Bu ilan incelemede; henüz herkese açık değil.</p>':''}<div class="comment-heading"><div><span class="eyebrow">ARACI BİLENLER ANLATIYOR</span><h2>İlan yorumları <span>(${d.comments.filter(c=>c.status==='approved').length})</span></h2></div>${v.status==='approved'?`<button class="button dark" data-action="comment" data-id="${id}">Deneyimini paylaş ${icon('plus','inline-icon')}</button>`:''}</div><p class="muted">İlişki etiketleri kullanıcı beyanıdır; sahiplik veya ekspertiz belgesi doğrulaması yapılmamıştır.</p><div class="comment-list">${d.comments.length?d.comments.map(c=>`<article class="comment"><div class="comment-meta"><span class="avatar">${esc(c.name.slice(0,2).toLocaleUpperCase('tr'))}</span><div><strong>${esc(c.name)}</strong><span>${date(c.created)}</span></div><span class="role-tag">${esc(c.role)}</span></div>${c.status!=='approved'?`<p class="notice">${c.status==='pending'?'Yorumun incelemede. Şimdilik yalnızca sen görebilirsin.':'Bu yorum yayımlanmadı.'}</p>`:''}<p class="comment-body">${esc(c.body)}</p>${c.status==='approved'?`<div class="comment-actions"><button class="text-button ${c.voted?'accent':''}" data-action="vote" data-id="${c.id}" data-vehicle="${id}">${icon('check','inline-icon')} Faydalı (${c.helpful})</button><button class="text-button" data-action="report" data-id="${c.id}">Şikâyet et</button></div>`:''}</article>`).join(''):'<div class="empty compact"><h3>İlk sözü sen söyle.</h3><p>Bu ilanı tanıyor musun? Deneyimini paylaşarak birine yol göster.</p></div>'}</div></section><aside class="detail-sidebar"><div class="side-card"><span class="eyebrow">SON ONAYLANAN FİYAT KAYDI</span><h2>${money(d.prices[0]?.amount)}</h2><p>Kullanıcıların bildirdiği fiyatlar.</p><hr><div class="price-heading"><h3>Fiyat kayıtları</h3><span>${icon('arrow-up-right','inline-icon')}</span></div>${d.prices.length?`<ol class="timeline">${d.prices.map(p=>`<li><span>${date(p.observed)}</span><strong>${money(p.amount)}</strong><small>${esc(p.name)} tarafından bildirildi</small></li>`).join('')}</ol>`:'<p class="muted">Henüz onaylanan fiyat kaydı yok.</p>'}${d.myPrices?.length?`<div class="my-price-records"><h3>Fiyat bildirimlerin</h3>${d.myPrices.map(p=>`<div class="my-price-record"><strong>${money(p.amount)}</strong><span class="status status-${esc(p.status)}">${statusText(p.status)}</span></div>`).join('')}</div>`:''}${v.status==='approved'?`<button class="button light full" data-action="price" data-id="${id}">Fiyat kaydı ekle ${icon('plus','inline-icon')}</button>`:''}<p class="fineprint">Otomatik fiyat takibi yapılmaz. Kayıtlar kullanıcı beyanıdır; geçmişin tamamını temsil etmez.</p></div><div class="side-card green"><span>${icon('sparkles','inline-icon')}</span><h3>Açık sözlü ol. Adil ol.</h3><p>Yaşadığını anlat, kişisel bilgileri paylaşma. İddianı gözleminden ayır. Her yorum yayımlanmadan önce incelenir.</p><a href="/guide">Topluluk kuralları ${icon('arrow-up-right','inline-icon')}</a></div></aside></div></main>`+footer();if(v.status==='suspended'||v.status==='removed')app.querySelector('.detail-layout')?.setAttribute('inert','');}
function commentForm(id){if(!needUser())return;openModal('Senin deneyimin ne?',`<p class="muted">Samimi, somut ve saygılı ol. Sadece bildiğini anlat.</p><form id="comment-form" class="form" data-id="${id}"><label>Bu araçla ilişkin<select name="role">${options(state.roles)}</select></label><p class="fineprint">Bu etiket senin beyanındır; doğrulanmış sahiplik anlamına gelmez.</p><label>Deneyimin<textarea name="body" required minlength="30" maxlength="3000" rows="6" placeholder="Aracı ne zaman, hangi koşullarda gördün? Neleri gözlemledin? Kişisel bilgi ve hakaret içermeden anlat."></textarea></label><label class="checkbox"><input type="checkbox" required><span>Yorumum kendi deneyimimi yansıtıyor ve kişisel bilgi içermiyor.</span></label><p class="form-error" role="alert"></p><button class="button orange full">İncelemeye gönder ${icon('arrow-up-right','inline-icon')}</button></form>`);}
function priceForm(id){if(!needUser())return;openModal('Fiyat kaydı ekle.',`<p class="muted">İlanda gördüğün tutarı ve tarihi paylaş. Yönetici incelemesinden sonra kayıtlara eklenecek.</p><form id="price-form" class="form" data-id="${id}"><label>Gördüğün fiyat (TL)<input type="number" name="amount" required min="1" max="1000000000"></label><label>Gördüğün tarih<input type="date" name="observed" required min="2000-01-01" max="${new Date().toISOString().slice(0,10)}" value="${new Date().toISOString().slice(0,10)}"></label><p class="form-error" role="alert"></p><button class="button orange full">İncelemeye gönder ${icon('arrow-up-right','inline-icon')}</button></form>`);}
async function editListing(id){if(!needUser())return;const {vehicle:v}=await api('/vehicles/'+id);openModal('İlan kategorisini düzenle.',`<p class="muted">İlan numarası değiştirilemez. Kategori değişikliği yeniden incelemeye gönderilir.</p><form id="edit-vehicle-form" class="form" data-id="${esc(id)}"><label>İlan numarası<input value="${esc(v.listing_no||'—')}" disabled></label><label>Kategori<select name="category" required>${state.categories.map(x=>`<option value="${esc(x)}"${x===v.category?' selected':''}>${esc(x)}</option>`).join('')}</select></label><p class="form-error" role="alert"></p><button class="button orange full" type="submit">Kategoriyi kaydet</button></form>`);}
function removeListing(id){openModal('İlanı kaldır?',`<p class="muted">İlan herkese kapatılır. Yayından kaldırılan ilanı yalnızca yönetici geri getirebilir.</p><form id="remove-vehicle-form" class="form" data-id="${esc(id)}"><p class="form-error" role="alert"></p><button class="button dark full" type="submit">Evet, ilanı kaldır</button></form>`);}
async function account(){if(!state.user){home();auth();return;}const d=await api('/account'),live=d.vehicles.filter(v=>v.status==='approved').length,pending=d.vehicles.filter(v=>v.status==='pending').length;app.innerHTML=header()+`<main class="wrap account account-dashboard"><div class="account-hero"><div><span class="eyebrow">HESABIM</span><h1>Merhaba, ${esc(state.user.name)}.</h1><p>İlanlarını, yorumlarını ve fiyat kayıtlarını tek yerden takip et.</p></div><div class="account-actions">${state.user.admin?`<a class="button dark" href="#/admin">İnceleme paneli ${icon('arrow-up-right','inline-icon')}</a>`:''}<button class="button outline" data-action="logout">Çıkış yap</button></div></div><div class="account-metrics"><div><strong>${d.vehicles.length}</strong><span>Eklediğin ilan</span></div><div><strong>${live}</strong><span>Yayında</span></div><div><strong>${pending}</strong><span>İncelemede</span></div><div><strong>${d.comments.length}</strong><span>Yorumun</span></div></div><section class="account-section"><div class="account-section-head"><div><span class="eyebrow">İLANLARIM</span><h2>Eklediğin ilanlar</h2></div><button class="button dark" data-action="add">Yeni ilan ekle ${icon('plus','inline-icon')}</button></div>${d.vehicles.length?`<div class="account-list">${d.vehicles.map(v=>`<article class="account-item"><div class="account-item-main"><span class="account-item-number">#${esc(v.listing_no||'—')}</span><h3>İlan #${esc(v.listing_no||v.id)}</h3><span class="status status-${esc(v.status)}">${statusText(v.status)}</span></div><div class="account-item-actions">${v.status==='removed'&&!v.owner_removed?'':`<a class="button outline" href="/ilan/${v.id}">Görüntüle</a>`}${v.status==='suspended'||v.status==='removed'&&!v.owner_removed?'':`<button class="button outline" data-action="edit-listing" data-id="${v.id}">Düzenle</button>`}${v.status==='removed'&&v.owner_removed?`<button class="button dark" data-action="restore-listing" data-id="${v.id}">Yeniden gönder</button>`:v.status!=='removed'&&v.status!=='suspended'?`<button class="button outline" data-action="remove-listing" data-id="${v.id}">Kaldır</button>`:''}</div></article>`).join('')}</div>`:'<div class="account-empty">Henüz ilan eklemedin. İlk ilan numaranla bir yorum sayfası açabilirsin.</div>'}</section><div class="account-columns"><section class="account-section"><div class="account-section-head"><div><span class="eyebrow">DENEYİMLERİM</span><h2>Yorumların</h2></div></div>${d.comments.length?d.comments.map(c=>`<a class="account-contribution" href="/ilan/${c.vehicle_id}"><div><strong>İlan #${esc(c.listing_no||c.vehicle_id)}</strong><p>${esc(c.body)}</p></div><span class="status status-${esc(c.status)}">${c.status==='approved'&&!['approved','suspended'].includes(c.vehicle_status)?'İlan yayını bekliyor':statusText(c.status)}</span></a>`).join(''):'<p class="account-empty">Henüz yorum paylaşmadın.</p>'}</section><section class="account-section"><div class="account-section-head"><div><span class="eyebrow">FİYAT GEÇMİŞİ</span><h2>Fiyat kayıtların</h2></div></div>${d.prices.length?d.prices.map(p=>`<a class="account-contribution" href="/ilan/${p.vehicle_id}"><div><strong>İlan #${esc(p.listing_no||p.vehicle_id)}</strong><p>${money(p.amount)}</p></div><span class="status status-${esc(p.status)}">${p.status==='approved'&&!['approved','suspended'].includes(p.vehicle_status)?'İlan yayını bekliyor':statusText(p.status)}</span></a>`).join(''):'<p class="account-empty">Henüz fiyat kaydı eklemedin.</p>'}</section></div></main>`+footer();}
const statusText=s=>({pending:'İncelemede',pending_listing:'İlan yayını bekliyor',approved:'Yayında',rejected:'Reddedildi',suspended:'Askıda',removed:'Kaldırıldı',resolved:'Kapandı',open:'Açık',active:'Aktif',owner_update:'İlan bilgisi düzenlendi',owner_remove:'İlan sahibi kaldırdı',owner_restore:'İlan sahibi yeniden gönderdi',update:'Bilgiler düzenlendi',remove:'Kaldırıldı',restore:'Geri yüklendi'}[s]||s);
const ADMIN_VIEW_KEY='sari-admin-view';let adminView={tab:'overview',category:'Tümü',filters:{},pages:{},scroll:0};try{adminView={...adminView,...JSON.parse(sessionStorage.getItem(ADMIN_VIEW_KEY)||'{}')};}catch{}const persistAdminView=()=>sessionStorage.setItem(ADMIN_VIEW_KEY,JSON.stringify(adminView));let adminActiveTab=adminView.tab||'overview',adminVehicleCategory=adminView.category||'Tümü';
const moderationButton=(kind,id,status,label,style='outline',compact=false,reviewFlags='')=>{const kindLabel={vehicles:'İlanı',comments:'Yorumu',prices:'Fiyat kaydını',users:'Üyeyi',reports:'Şikâyeti'}[kind]||'Kaydı';const actionIcon={approved:'check',rejected:'x',suspended:'pause',removed:'trash',active:'play',resolved:'check',open:'rotate-ccw'}[status]||'check';const actionTitle=label==='Reddet'?'Reddet: incelemedeki içerik yayımlanmaz.':label==='Kaldır'||label==='Yorumu kaldır'?'Kaldır: içerik yayından alınır.':label==='Askıya al'?'Askıya al: etkileşimleri geçici olarak durdur.':label;return `<button type="button" class="button ${style}${compact?' moderation-icon':''}" data-action="moderate" data-kind="${kind}" data-id="${esc(id)}" data-status="${status}"${reviewFlags?` data-review-flags="${esc(reviewFlags)}"`:''}${compact?` aria-label="${esc(kindLabel+' '+label.toLocaleLowerCase('tr'))}" title="${esc(kindLabel+' · '+actionTitle)}"`:''}>${compact?icon(actionIcon):esc(label)}</button>`;};
function contentActions(kind,r,compact=false){const act=(status,label,style='outline',targetKind=kind,targetId=r.id)=>moderationButton(targetKind,targetId,status,label,style,compact,kind==='comments'&&status==='approved'?r.review_flags:'');if(kind==='users')return r.is_admin?'<span class="admin-badge">Yönetici</span>':r.is_suspended?act('active','Erişimi aç','dark'):act('suspended','Üyeyi askıya al','danger');if(kind==='reports')return r.status==='open'?act('removed','Yorumu kaldır','danger','comments',r.comment_id)+act('resolved','Şikâyeti kapat','dark'):act('open','Yeniden aç');if((kind==='comments'||kind==='prices')&&r.status==='pending'&&r.vehicle_status!=='approved')return '<span class="table-note">İlan yayına alınmalı</span>'+act('rejected','Reddet','danger');if(r.status==='approved')return act('suspended','Askıya al')+act('removed','Kaldır','danger');if(r.status==='suspended')return act('approved','Yayına al','dark')+act('removed','Kaldır','danger');if(r.status==='removed')return act('approved','Geri yükle','dark');if(r.status==='rejected')return act('approved','Yayına al','dark');return act('approved','Onayla','dark')+act('rejected','Reddet','danger');}
function vehicleActions(v){return contentActions('vehicles',v);}
function tableRow(kind,r){const status=kind==='users'?(r.is_admin?'admin':r.is_suspended?'suspended':'active'):r.status;let main='',detail='';if(kind==='vehicles'){main=`İlan #${r.listing_no||r.id}`;detail='';}else if(kind==='comments'){main=`İlan #${r.listing_no||r.vehicle_id}`;detail=r.body+(r.review_flags?` · Ek inceleme: ${r.review_flags}`:'');}else if(kind==='prices'){main=`İlan #${r.listing_no||r.vehicle_id}`;detail=`${money(r.amount)} · ${date(r.observed)}`;}else if(kind==='reports'){main=`İlan #${r.listing_no||r.vehicle_id}`;detail=r.body; }else{main=r.name;detail=r.email;}const owner=kind==='users'?(r.is_admin?'Yönetici hesabı':'Üye hesabı'):r.name||'—';const category=kind==='vehicles'?r.category:kind==='comments'?`${r.role||'Yorum'} · İlan: ${statusText(r.vehicle_status)}`:kind==='prices'?`Fiyat kaydı · İlan: ${statusText(r.vehicle_status)}`:kind==='reports'?r.reason||'Yorum şikâyeti':date(r.created);const link=kind==='vehicles'?`<a class="table-link-icon" href="/ilan/${esc(r.id)}" aria-label="İlanı aç" title="İlanı aç">${icon('arrow-up-right')}</a>`:kind==='comments'||kind==='prices'?`<a class="table-link-icon" href="/ilan/${esc(r.vehicle_id)}" aria-label="İlanı aç" title="İlanı aç">${icon('arrow-up-right')}</a>`:'';return `<tr><td><strong>${esc(main||'—')}</strong><small>${esc(detail||'')}</small></td><td>${esc(category||'—')}</td><td>${esc(owner)}</td><td><span class="status status-${esc(status)}">${status==='admin'?'Yönetici':status==='approved'&&(kind==='comments'||kind==='prices')&&!['approved','suspended'].includes(r.vehicle_status)?'İlan yayını bekliyor':statusText(status)}</span></td><td>${date(r.created)}</td><td><div class="table-actions">${link}${contentActions(kind,r,true)}</div></td></tr>`;}
function adminSection(kind,label,rows,columns){return `<section class="admin-tab-panel" role="tabpanel" id="admin-panel-${kind}" data-admin-panel="${kind}" hidden><div class="admin-section-heading"><div><span class="eyebrow">YÖNETİM</span><h2>${label} <span id="admin-count-${kind}">${rows.length}</span></h2></div><p>${kind==='users'?'Üye erişimini yönetin.':kind==='reports'?'Şikâyetleri inceleyin ve sonuçlandırın.':'Reddet: incelemedeki kayıt yayımlanmaz. Kaldır: yayımlanmış içerik yayından alınır.'}</p></div><div class="admin-filters"><label class="admin-search">Ara<input type="search" data-admin-search="${kind}" placeholder="${kind==='users'?'Ad veya e-posta':'İlan no veya üye'}"></label><label>Durum<select data-admin-status="${kind}"><option value="all">Tüm durumlar</option>${(kind==='reports'?['open','resolved']:kind==='users'?['active','suspended']:['pending','approved','suspended','rejected','removed']).map(v=>`<option value="${v}">${statusText(v)}</option>`).join('')}</select></label></div>${kind==='vehicles'?`<div class="admin-category-tabs" role="tablist" aria-label="İlan kategorileri"><button type="button" class="${adminVehicleCategory==='Tümü'?'selected':''}" data-vehicle-category="Tümü">Tüm kategoriler</button>${[...new Set([...state.categories,...rows.map(r=>r.category)])].map(c=>`<button type="button" class="${adminVehicleCategory===c?'selected':''}" data-vehicle-category="${esc(c)}">${esc(c)}</button>`).join('')}</div>`:''}<div class="table-scroll"><table class="management-table"><thead><tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody id="admin-tbody-${kind}"></tbody></table><p class="admin-empty" id="admin-empty-${kind}" hidden>Bu filtreye uygun kayıt yok.</p></div><div class="admin-pagination"><span id="admin-page-${kind}"></span><div><button class="button outline" type="button" data-admin-prev="${kind}">Önceki</button><button class="button outline" type="button" data-admin-next="${kind}">Sonraki</button></div></div></section>`;}
async function adminPage(){if(!state.user?.admin)throw new Error('Yönetici girişi gerekiyor.');const previous=app.querySelector('.admin-dashboard');if(previous){adminView.scroll=window.scrollY;persistAdminView();}const focused=document.activeElement?.dataset.adminSearch||null;const d=await api('/admin');if(routeHash()!=='#/admin')return;const queued=d.vehicles.filter(v=>v.status==='pending').length+d.comments.filter(v=>v.status==='pending').length+d.prices.filter(v=>v.status==='pending').length+d.reports.filter(v=>v.status==='open').length,live=d.vehicles.filter(v=>v.status==='approved').length,suspended=d.vehicles.filter(v=>v.status==='suspended').length;const html=header()+`<main class="wrap account admin-dashboard"><div class="admin-title"><div><span class="eyebrow">SİTE YÖNETİMİ</span><h1>Kontrol merkezi</h1><p class="muted">İlanlar, kategoriler, topluluk katkıları ve üye erişimi tek yerde.</p></div><a class="button outline" href="/">Siteye dön ${icon('arrow-up-right','inline-icon')}</a></div><div class="admin-stats"><article><span>Yayındaki ilan</span><strong>${live}</strong></article><article><span>İnceleme bekliyor</span><strong>${queued}</strong></article><article><span>Askıda içerik</span><strong>${suspended+d.comments.filter(x=>x.status==='suspended').length+d.prices.filter(x=>x.status==='suspended').length}</strong></article><article><span>Üye / askıda üye</span><strong>${d.userCount} <small>/${d.users.filter(x=>x.is_suspended).length}</small></strong></article></div><nav class="admin-tabs" role="tablist" aria-label="Yönetim bölümleri">${[['overview','Genel bakış'],['vehicles','İlanlar'],['comments','Yorumlar'],['prices','Fiyat kayıtları'],['reports','Şikâyetler'],['users','Üyeler']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${adminActiveTab===id}" class="${adminActiveTab===id?'active':''}" data-admin-tab="${id}">${label}<span>${id==='vehicles'?d.vehicles.filter(x=>x.status==='pending').length:id==='comments'?d.comments.filter(x=>x.status==='pending').length:id==='prices'?d.prices.filter(x=>x.status==='pending').length:id==='reports'?d.reports.filter(x=>x.status==='open').length:id==='users'?d.userCount:''}</span></button>`).join('')}</nav><section class="admin-tab-panel admin-overview" role="tabpanel" data-admin-panel="overview"><div class="admin-overview-grid"><article><span class="eyebrow">İŞ SIRASI</span><h2>${queued} kayıt inceleme bekliyor</h2><p>Bekleyen içerikleri ilgili sekmede onaylayabilir veya reddedebilirsin.</p><button class="button dark" type="button" data-admin-tab="vehicles">İlanları incele</button><button class="button outline" type="button" data-admin-tab="comments">Yorumları incele</button><button class="button outline" type="button" data-admin-tab="prices">Fiyatları incele</button></article><article><span class="eyebrow">SON İŞLEMLER</span>${d.audit.length?`<div class="audit-list">${d.audit.slice(0,8).map(a=>`<div><span>${esc(a.admin_name)} · ${date(a.created)}</span><strong>${esc(a.kind)} · ${statusText(a.action)}</strong></div>`).join('')}</div>`:'<p class="muted">Henüz yönetim işlemi yok.</p>'}</article></div></section>${adminSection('vehicles','Tüm ilanlar',d.vehicles,['İlan numarası','Kategori','Ekleyen','Durum','Tarih','Kontroller'])}${adminSection('comments','Tüm yorumlar',d.comments,['İlan / yorum','İlişki','Üye','Durum','Tarih','Kontroller'])}${adminSection('prices','Fiyat bildirimleri',d.prices,['İlan / fiyat','Tarih','Üye','Durum','Gönderim','Kontroller'])}${adminSection('reports','Şikâyet kayıtları',d.reports,['İlan / yorum','Şikâyet nedeni','Bildiren','Durum','Tarih','Kontroller'])}${adminSection('users','Üye yönetimi',d.users,['Üye','Hesap','Erişim','Durum','Kayıt','Kontroller'])}</main>`+footer();if(previous){const holder=document.createElement('div');holder.innerHTML=html;previous.replaceWith(holder.querySelector('main'));}else app.innerHTML=html;const records={vehicles:d.vehicles,comments:d.comments,prices:d.prices,reports:d.reports,users:d.users},page=Object.fromEntries(Object.keys(records).map(k=>[k,Number(adminView.pages?.[k])||0]));let selectedCategory=adminVehicleCategory;for(const kind of Object.keys(records)){const saved=adminView.filters?.[kind]||{};app.querySelector(`[data-admin-search="${kind}"]`).value=saved.query||'';app.querySelector(`[data-admin-status="${kind}"]`).value=saved.status||'all';}const filterRows=kind=>{const query=app.querySelector(`[data-admin-search="${kind}"]`).value.trim().toLocaleLowerCase('tr'),status=app.querySelector(`[data-admin-status="${kind}"]`).value;let rows=records[kind].filter(r=>{const s=kind==='users'?(r.is_suspended?'suspended':'active'):r.status;return(status==='all'||s===status)&&`${r.listing_no||''} ${r.body||''} ${r.reason||''} ${r.name||''} ${r.email||''} ${r.amount||''}`.toLocaleLowerCase('tr').includes(query);});if(kind==='vehicles'&&selectedCategory!=='Tümü')rows=rows.filter(r=>r.category===selectedCategory);return rows;};const draw=kind=>{const rows=filterRows(kind),pages=Math.max(1,Math.ceil(rows.length/50)),p=page[kind]=Math.max(0,Math.min(page[kind],pages-1)),slice=rows.slice(p*50,(p+1)*50);adminView.pages[kind]=p;app.querySelector(`#admin-tbody-${kind}`).innerHTML=slice.map(r=>tableRow(kind,r)).join('');app.querySelector(`#admin-empty-${kind}`).hidden=!!slice.length;app.querySelector(`#admin-page-${kind}`).textContent=rows.length?`${p*50+1}–${Math.min((p+1)*50,rows.length)} / ${rows.length}`:'0 kayıt';app.querySelector(`[data-admin-prev="${kind}"]`).disabled=p===0;app.querySelector(`[data-admin-next="${kind}"]`).disabled=p>=pages-1;};for(const kind of Object.keys(records)){draw(kind);app.querySelector(`[data-admin-search="${kind}"]`).addEventListener('input',e=>{adminView.filters[kind]={...adminView.filters[kind],query:e.target.value};page[kind]=0;draw(kind);persistAdminView();});app.querySelector(`[data-admin-status="${kind}"]`).addEventListener('change',e=>{adminView.filters[kind]={...adminView.filters[kind],status:e.target.value};page[kind]=0;draw(kind);persistAdminView();});app.querySelector(`[data-admin-prev="${kind}"]`).addEventListener('click',()=>{page[kind]--;draw(kind);persistAdminView();});app.querySelector(`[data-admin-next="${kind}"]`).addEventListener('click',()=>{page[kind]++;draw(kind);persistAdminView();});}const activate=tab=>{adminActiveTab=adminView.tab=tab;persistAdminView();app.querySelectorAll('[data-admin-tab]').forEach(b=>{const active=b.dataset.adminTab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});app.querySelectorAll('[data-admin-panel]').forEach(p=>p.hidden=p.dataset.adminPanel!==tab);};app.querySelectorAll('[data-admin-tab]').forEach(b=>b.addEventListener('click',()=>activate(b.dataset.adminTab)));app.querySelectorAll('[data-vehicle-category]').forEach(b=>b.addEventListener('click',()=>{selectedCategory=adminVehicleCategory=adminView.category=b.dataset.vehicleCategory;page.vehicles=0;persistAdminView();app.querySelectorAll('[data-vehicle-category]').forEach(x=>x.classList.toggle('selected',x===b));draw('vehicles');}));activate(adminActiveTab);if(focused){const input=app.querySelector(`[data-admin-search="${focused}"]`);input?.focus({preventScroll:true});}requestAnimationFrame(()=>{if(routeHash()==='#/admin')window.scrollTo(0,adminView.scroll||0);});}
async function info(path){const response=await fetch('/legal.json');if(!response.ok)throw Error('Bilgilendirme sayfası yüklenemedi.');const page=(await response.json())[path.slice(1)];if(!page)throw Error('Sayfa bulunamadı.');app.innerHTML=header()+`<main class="wrap prose legal-page"><span class="eyebrow">SARI SİTE YORUMLA</span><h1>${page.heading}</h1>${page.intro}${page.sections.map(([heading,body])=>`<section><h2>${heading}</h2>${body}</section>`).join('')}<a class="button dark" href="/">İlanları keşfet ${icon('arrow-up-right','inline-icon')}</a></main>`+footer();}
let routeVersion=0;async function route(){const version=++routeVersion;try{const hash=routeHash(),m=hash.match(/^#\/vehicle\/([\w-]+)$/);if(m)await detail(m[1]);else if(hash==='#/account')await account();else if(hash==='#/admin')await adminPage();else if(['#/about','#/terms','#/guide','#/privacy','#/cookies'].includes(hash))await info(hash.slice(1));else{if(hash==='#/takip'&&!state.user){state.onlyFollow=false;home();auth();return;}state.onlyFollow=hash==='#/takip';const d=await api(vehiclePath());if(version!==routeVersion)return;state.vehicles=d.vehicles;state.total=d.total;state.hasMore=d.hasMore;home();}if(hash==='#/takip')$('#explore')?.scrollIntoView({block:'start'});else if(hash!=='#/admin')window.scrollTo(0,0);}catch(e){if(/bulunamadı/i.test(e.message)&&routeHash().startsWith('#/vehicle/')){app.innerHTML=header()+`<main class="wrap prose"><h1>404 · İlan bulunamadı</h1><p>Bu ilan yayında değil veya bağlantı artık geçerli değil.</p><a class="button dark" href="/">İlanları keşfet</a></main>`+footer();return;}toast(e.message);app.innerHTML=header()+`<main class="wrap prose"><h1>Burada bir sorun var.</h1><p>${esc(e.message)}</p><a class="button dark" href="/">Ana sayfaya dön</a></main>`+footer();}}
let liveSource=null,liveTimer=null,liveBusy=false;const liveQueue=[];
function connectLive(){liveSource?.close();if(!window.EventSource)return;liveSource=new EventSource('/api/events');liveSource.onmessage=e=>{try{queueLive(JSON.parse(e.data));}catch{}};liveSource.onopen=()=>queueLive({kind:'vehicles'});}
function queueLive(event){if(!event||typeof event.kind!=='string')return;if(document.hidden)return;if(!liveQueue.some(e=>e.kind===event.kind&&e.vehicleId===event.vehicleId))liveQueue.push(event);clearTimeout(liveTimer);liveTimer=setTimeout(flushLive,120);}
async function refreshVehicleGrid(){const target=Math.max(24,state.vehicles.length);let offset=0,items=[],latest;do{latest=await api(vehiclePath(offset));items.push(...latest.vehicles);offset=items.length;}while(latest.hasMore&&items.length<target);if(!$('#grid'))return;state.vehicles=items;state.total=latest.total;state.hasMore=latest.hasMore;renderGrid();}
async function flushLive(){if(liveBusy||modal.open||document.hidden||!liveQueue.length)return;liveBusy=true;const events=liveQueue.splice(0),current=routeHash(),y=window.scrollY;try{if(current==='#/admin'&&state.user?.admin)await adminPage();else if(current==='#/account'&&state.user&&events.some(e=>['vehicles','comments','prices','users'].includes(e.kind)))await account();else if(current.startsWith('#/vehicle/')){const id=current.slice(10);if(events.some(e=>!e.vehicleId||e.vehicleId===id))await detail(id);}else if((current==='#/'||current==='#/takip')&&events.some(e=>['vehicles','comments','prices'].includes(e.kind)))await refreshVehicleGrid();if(current===routeHash()&&current!=='#/admin')window.scrollTo(0,y);}catch(error){if(/bulunamadı/i.test(error.message)&&current.startsWith('#/vehicle/'))await route();else if(error.message)console.warn('Canlı güncelleme alınamadı:',error.message);}finally{liveBusy=false;if(liveQueue.length)liveTimer=setTimeout(flushLive,120);}}
function resyncLive(){if(!document.hidden)queueLive({kind:'vehicles'});}
document.addEventListener('visibilitychange',resyncLive);window.addEventListener('pageshow',resyncLive);window.addEventListener('focus',resyncLive);
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(a==='menu-toggle'){const header=el.closest('header'),open=el.getAttribute('aria-expanded')!=='true';el.setAttribute('aria-expanded',String(open));el.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');header.classList.toggle('mobile-menu-open',open);return;}if(el.closest('.mobile-menu')){const header=el.closest('header'),toggle=header?.querySelector('.mobile-menu-toggle');header?.classList.remove('mobile-menu-open');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Menüyü aç');}if(a==='copy-listing'){try{await navigator.clipboard.writeText(el.dataset.number);toast('İlan numarası kopyalandı.');}catch{toast('İlan numarası kopyalanamadı.');}return;}if(a==='close')return modal.close();if(a==='login'||a==='register'){if(modal.open)modal.close();return auth(a==='register');}if(a==='add')return addVehicle();if(a==='account')return navigate('/account');if(a==='rules'||a==='privacy'){modal.close();return navigate(a==='rules'?'/guide':'/privacy');}if(a==='category'){state.category=el.dataset.category;await loadVehicles();home();$('#explore')?.scrollIntoView({block:'start'});return;}if(a==='more'){await loadVehicles(false);return;}if(a==='follow-nav'){if(!needUser())return;return navigate('/takip');}if(a==='all')return navigate('/');if(a==='logout'){await api('/logout',{});state.user=null;connectLive();return navigate('/');}if(a==='follow'||a==='follow-detail'){if(!needUser())return;const d=await api('/vehicles/'+id+'/follow',{});const v=state.vehicles.find(v=>v.id===id);if(v)v.following=Number(d.following);if(a==='follow-detail')await detail(id);else await loadVehicles();toast(d.following?'Takip listene eklendi.':'Takip listenden çıkarıldı.');return;}if(a==='edit-listing')return editListing(id);if(a==='remove-listing')return removeListing(id);if(a==='restore-listing'){await api('/vehicles/'+id+'/manage',{action:'restore'});toast('İlan yeniden incelemeye gönderildi.');return routeHash()==='#/account'?account():detail(id);}if(a==='comment')return commentForm(id);if(a==='price')return priceForm(id);if(a==='vote'){if(!needUser())return;await api('/comments/'+id+'/vote',{});await detail(el.dataset.vehicle);return;}if(a==='report'){if(!needUser())return;openModal('Yorumu bildir.',`<p class="muted">Sorunu açıkla. Yönetici yorumu yeniden inceleyecek.</p><form id="report-form" class="form" data-id="${id}"><label>Şikâyet nedeni<textarea name="reason" required minlength="10" maxlength="500" rows="4"></textarea></label><p class="form-error" role="alert"></p><button class="button orange full">Bildirimi gönder</button></form>`);return;}if(a==='moderate'){const kind=el.dataset.kind,status=el.dataset.status,flags=el.dataset.reviewFlags;let overrideFlagged=false;if(kind==='comments'&&status==='approved'&&flags){overrideFlagged=window.confirm(`Bu yorum ek inceleme için işaretlendi: ${flags}.\n\nYorumu okuduktan sonra yine de yayımlamak istiyor musun?`);if(!overrideFlagged)return;}await api('/admin/moderate',{kind,id,status,overrideFlagged});if(kind==='vehicles'&&routeHash().match(/^#\/vehicle\//))await detail(id);else await adminPage();toast(status==='suspended'?'İçerik askıya alındı.':status==='removed'?'İçerik kaldırıldı.':status==='approved'?'İçerik yayına alındı.':status==='active'?'Üye erişimi açıldı.':status==='resolved'?'Şikâyet kapatıldı.':'İşlem kaydedildi.');}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();handleAction(el).catch(err=>toast(err.message));});
document.addEventListener('click',e=>{const header=$('header.mobile-menu-open'),target=e.target instanceof Element?e.target:null;if(!header||target?.closest('.mobile-menu,.mobile-menu-toggle'))return;header.classList.remove('mobile-menu-open');const toggle=header.querySelector('.mobile-menu-toggle');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Menüyü aç');});
document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(!link||link.closest('[data-action]')||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||link.target==='_blank'||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!['http:','https:'].includes(url.protocol))return;e.preventDefault();const legacyPath=url.hash.startsWith('#/')?url.hash.slice(1).replace(/^\/vehicle\//,'/ilan/'):null;navigate(legacyPath||url.pathname+url.search+url.hash).catch(err=>toast(err.message));});
document.addEventListener('change',e=>{if(e.target.id==='sort'){state.sort=e.target.value;loadVehicles().catch(err=>toast(err.message));}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f));if(f.id==='search'){const raw=b.query.trim(),match=raw.match(/^\d{8,12}$/)||raw.match(/^https:\/\/(?:www\.)?sahibinden\.com\/ilan\/[^?#]*-(\d{8,12})(?:\/detay)?(?:[?#].*)?$/);if(match){try{const found=await api('/listings?number='+encodeURIComponent(match[1]||match[0]));if(found.id){location.hash='/vehicle/'+found.id;return;}const feedback=$('#search-feedback');feedback.textContent=found.status==='pending'?'Bu ilan numarası için bir sayfa açılmış; şu anda incelemede. Onaylandığında burada bulabilirsin.':'Bu ilan numarasıyla henüz bir yorum sayfası bulamadık.';feedback.hidden=false;return;}catch(err){toast(err.message);return;}}state.query=raw;await loadVehicles();$('#explore')?.scrollIntoView({behavior:'smooth'});return;}const btn=f.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;const err=f.querySelector('.form-error');if(err)err.textContent='';try{if(f.id==='auth-form'){const register=f.dataset.register==='true',d=await api(register?'/register':'/login',{...b,acceptTerms:b.acceptTerms==='on',acceptRules:b.acceptRules==='on'});state.user=d.user;connectLive();modal.close();toast(register?'Hoş geldin. Hikâyeye sen de katıldın.':'Giriş yaptın.');await route();if(state.pendingListing){const pending=state.pendingListing;state.pendingListing=null;addVehicle();$('#listing-form input[name=listing]').value=pending;}}else if(f.id==='listing-form'){const d=await api('/listings',b);modal.close();toast(d.pending?'İlan incelemeye gönderildi. Onaylanınca yayımlanacak.':'İlan sayfası hazır.');location.hash='/vehicle/'+d.id;await route();}else if(['comment-form','price-form'].includes(f.id)){await api('/vehicles/'+f.dataset.id+(f.id==='comment-form'?'/comments':'/prices'),b);modal.close();toast('Katkın alındı. İnceleme sonrasında yayımlanacak.');await detail(f.dataset.id);}else if(f.id==='edit-vehicle-form'||f.id==='remove-vehicle-form'){const action=f.id==='edit-vehicle-form'?'update':'remove';await api('/vehicles/'+f.dataset.id+'/manage',{...b,action});modal.close();toast(action==='update'?'İlan bilgileri kaydedildi.':'İlan kaldırıldı.');if(routeHash()==='#/account')await account();else await route();}else if(f.id==='report-form'){await api('/comments/'+f.dataset.id+'/report',b);modal.close();toast('Bildirimin yöneticilere iletildi.');}}catch(error){if(err)err.textContent=error.message;else toast(error.message);}finally{if(btn)btn.disabled=false;}});
modal.addEventListener('close',()=>{document.documentElement.classList.remove('modal-open');if(liveQueue.length)liveTimer=setTimeout(flushLive,0);});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',()=>{const raw=location.hash.slice(1),path=raw.replace(/^\/vehicle\//,'/ilan/')||'/';history.replaceState(null,'',path);smoothRoute();});
window.addEventListener('popstate',()=>smoothRoute());
let adminScrollTimer;window.addEventListener('scroll',()=>{if(routeHash()!=='#/admin'||!app.querySelector('.admin-dashboard'))return;clearTimeout(adminScrollTimer);adminScrollTimer=setTimeout(()=>{adminView.scroll=window.scrollY;persistAdminView();},120);},{passive:true});window.addEventListener('pagehide',()=>{if(routeHash()==='#/admin'){adminView.scroll=window.scrollY;persistAdminView();}});history.scrollRestoration='manual';
(async()=>{try{const [me,meta]=await Promise.all([api('/me'),api('/meta')]);Object.assign(state,{user:me.user,demo:me.demo,categories:meta.categories,roles:meta.roles});await route();connectLive();}catch(e){app.innerHTML='<main class="wrap prose"><h1>Bağlantı kurulamadı.</h1><p>Lütfen sayfayı yenile.</p></main>';toast(e.message);}finally{document.documentElement.classList.add('app-ready');finishIntro();}})();
